stageCss:
#stage .hb-scene{ position:relative; width:100%; height:100%; }#stage .hb-sc{
  position:absolute; inset:0; opacity:0; pointer-events:none;
  display:flex; flex-direction:column; gap:14px; transition:opacity .3s ease;
}#stage .hb-sc.on{ opacity:1; }#stage .hb-world{ flex:1; min-height:0; display:flex; flex-direction:column; gap:10px; }#stage .hb-row{ width:100%; display:flex; gap:16px; flex-shrink:0; }#stage .hb-tr{
  flex:1; min-width:0; height:250px; display:flex; flex-direction:column; align-items:center;
  justify-content:center; gap:14px; border-radius:30px; border:2px solid #2C3852;
  background:linear-gradient(180deg,#212B3F,#141B2B); box-shadow:0 18px 44px rgba(0,0,0,.45);
  transition:border-color .25s ease, box-shadow .25s ease;
}#stage .hb-tr.bad{ border-color:rgba(244,74,106,.7); box-shadow:inset 0 0 60px rgba(244,74,106,.16); }#stage .hb-tr.good{ border-color:rgba(63,185,80,.6); box-shadow:inset 0 0 60px rgba(63,185,80,.12); }#stage .hb-tr.warn{ border-color:rgba(240,166,74,.6); box-shadow:inset 0 0 60px rgba(240,166,74,.12); }#stage .hb-tr-h{ color:#fff; font-size:27px; font-weight:800; }#stage .hb-tr-room{ color:var(--text-dim); font-size:22px; font-weight:600; }#stage .hb-tr-t{ color:var(--text-primary); font-family:var(--font-mono); font-size:23px; font-weight:800; text-align:center; padding:0 12px; }#stage .hb-tr.bad .hb-tr-t{ color:var(--danger); }#stage .hb-tr.good .hb-tr-t{ color:var(--success); }#stage .hb-tr.warn .hb-tr-t{ color:var(--warn); }#stage .hb-ars{ height:44px; align-items:center; }#stage .hb-ars i{
  flex:1; text-align:center; font-style:normal; line-height:1; font-size:42px;
  color:var(--border); opacity:.35; transition:color .25s ease, opacity .25s ease, text-shadow .25s ease;
}#stage .hb-ars i.live{ color:var(--accent-1); opacity:1; text-shadow:0 0 24px rgba(58,160,255,.7); }#stage .hb-ars i.bad{ color:var(--danger); opacity:1; text-shadow:0 0 24px rgba(244,74,106,.6); }#stage .hb-ars i.ok{ color:var(--success); opacity:1; text-shadow:0 0 22px rgba(63,185,80,.5); }#stage .hb-hotel, #stage .hb-money{
  width:100%; flex-shrink:0; display:flex; align-items:center; gap:20px; padding:0 26px; border-radius:26px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2)); border:1.5px solid var(--border);
  transition:border-color .25s ease, box-shadow .25s ease;
}#stage .hb-hotel{ height:190px; }#stage .hb-money{ height:220px; }#stage .hb-hotel.live, #stage .hb-money.live{ border-color:rgba(58,160,255,.7); box-shadow:0 0 46px rgba(58,160,255,.2); }#stage .hb-hotel.bad, #stage .hb-money.bad{ border-color:rgba(244,74,106,.7); box-shadow:0 0 46px rgba(244,74,106,.18); }#stage .hb-hotel.ok, #stage .hb-money.ok{ border-color:rgba(63,185,80,.6); box-shadow:0 0 40px rgba(63,185,80,.14); }#stage .hb-hotel.warn, #stage .hb-money.warn{ border-color:rgba(240,166,74,.6); box-shadow:0 0 40px rgba(240,166,74,.14); }#stage .hb-h-ic, #stage .hb-m-ic{ font-size:64px; flex-shrink:0; }#stage .hb-h-bt, #stage .hb-m-bt{ display:flex; flex-direction:column; gap:4px; min-width:0; }#stage .hb-h-bt b, #stage .hb-m-bt b{ color:#fff; font-size:33px; font-weight:800; letter-spacing:-.5px; white-space:nowrap; }#stage .hb-h-bt small, #stage .hb-m-bt small{ color:var(--text-dim); font-size:21px; font-weight:600; white-space:nowrap; }#stage .hb-chip{
  padding:8px 16px; border-radius:100px; white-space:nowrap;
  background:rgba(139,149,167,.1); border:1.5px solid rgba(139,149,167,.3);
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:800;
}#stage .hb-chip.big{ margin-left:auto; flex-shrink:0; padding:12px 22px; font-size:25px; }#stage .hb-chip.ok{ background:rgba(63,185,80,.14); border-color:rgba(63,185,80,.5); color:var(--success); }#stage .hb-chip.bad{ background:rgba(244,74,106,.14); border-color:rgba(244,74,106,.5); color:var(--danger); }#stage .hb-chip.warn{ background:rgba(240,166,74,.14); border-color:rgba(240,166,74,.5); color:var(--warn); }#stage .hb-final{ height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:28px; text-align:center; }#stage .hb-badge{
  width:140px; height:140px; border-radius:38px; display:flex; align-items:center; justify-content:center; font-size:76px;
  background:linear-gradient(160deg,#26344E,#1A2338); border:1.5px solid rgba(58,160,255,.5); box-shadow:0 0 60px rgba(58,160,255,.2);
}#stage .hb-fin-h{ color:#fff; font-size:62px; font-weight:900; line-height:1.16; letter-spacing:-1.6px; }#stage .hb-fin-h em{ font-style:normal; color:var(--accent-1); }#stage .hb-fin-row{ display:flex; gap:14px; justify-content:center; }#stage .hb-fin-p{
  padding:16px 26px; border-radius:100px; white-space:nowrap;
  background:rgba(58,160,255,.1); border:1.5px solid rgba(58,160,255,.42);
  color:var(--text-primary); font-size:26px; font-weight:700;
}#stage .hb-save{
  padding:18px 30px; border-radius:20px; background:rgba(240,166,74,.1); border:1.5px solid rgba(240,166,74,.42);
  color:var(--warn); font-size:26px; font-weight:800; transition:transform .3s cubic-bezier(.22,1,.36,1), box-shadow .3s ease;
}#stage .hb-save.ping{ transform:scale(1.04); box-shadow:0 0 44px rgba(240,166,74,.24); }#stage .hb-strip{
  height:104px; flex-shrink:0; display:flex; align-items:center; gap:18px; padding:0 24px; border-radius:22px;
  background:rgba(20,27,43,.75); border:1.5px solid var(--border); transition:border-color .25s ease, background .25s ease;
}#stage .hb-strip.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.1); }#stage .hb-strip.good{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.1); }#stage .hb-strip b{
  flex-shrink:0; padding:10px 18px; border-radius:12px; font-family:var(--font-mono); font-size:19px; font-weight:800;
  letter-spacing:1.4px; color:var(--text-dim); background:rgba(139,149,167,.12); border:1.5px solid rgba(139,149,167,.22);
}#stage .hb-strip.bad b{ color:var(--danger); background:rgba(244,74,106,.16); border-color:rgba(244,74,106,.5); }#stage .hb-strip.good b{ color:var(--success); background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.5); }#stage .hb-strip span{ color:#fff; font-size:28px; font-weight:700; line-height:1.25; }

