var HB = window.__HB || (window.__HB = {});
// Column centres and row centres, in % of the scene.
HB.X = [27, 73];
HB.Y = { trav: 14, hotel: 42, money: 68 };

HB.scene = function(id){ MSD.cls('.hb-sc', 'on', false); MSD.cls('#hb-sc-' + id, 'on', true); };

HB.strip = function(label, text, tone){
  MSD.cls('#hb-strip', 'bad', tone === 'bad');
  MSD.cls('#hb-strip', 'good', tone === 'good');
  MSD.q('#hb-strip-l').textContent = label;
  MSD.q('#hb-strip-t').textContent = text;
};

HB.tr = function(i, text, tone){
  MSD.q('#hb-tr-t-' + i).textContent = text;
  ['bad','good','warn'].forEach(function(c){ MSD.cls('#hb-tr-' + i, c, tone === c); });
};

HB.ar = function(row, i, tone){
  ['live','bad','ok'].forEach(function(c){ MSD.cls('#hb-a' + row + '-' + i, c, tone === c); });
};

HB.box = function(sel, tone){ ['live','bad','ok','warn'].forEach(function(c){ MSD.cls(sel, c, tone === c); }); };
HB.chip = function(sel, text, tone){
  var v = MSD.q(sel); v.textContent = text;
  ['ok','bad','warn'].forEach(function(c){ v.classList.toggle(c, tone === c); });
};

HB.hotel = function(left, tone, sub){
  HB.box('#hb-hotel', tone);
  HB.chip('#hb-left', left, tone === 'ok' ? 'ok' : tone === 'bad' ? 'bad' : tone === 'warn' ? 'warn' : '');
  MSD.q('#hb-h-s').textContent = sub || '2 to 4 October';
};
HB.money = function(state, tone, sub){
  HB.box('#hb-money', tone);
  HB.chip('#hb-m-v', state, tone === 'live' ? '' : tone);
  MSD.q('#hb-m-s').textContent = sub || "the traveller's money";
};

// Something travelling between two rows. Travellers sit in two columns;
// the hotel and the money are one centred row each.
HB.go = function(col, fromRow, toRow, n){
  var fx = fromRow === 'trav' ? HB.X[col] : 50;
  var tx = toRow === 'trav' ? HB.X[col] : 50;
  MSD.particles('#hb-scene', { from:{ x:fx, y:HB.Y[fromRow] }, to:{ x:tx, y:HB.Y[toRow] }, count:n || 5, duration:650, spread:18 });
};

HB.reset = function(){
  HB.scene('world');
  HB.tr(1, '1 room left', ''); HB.tr(2, '1 room left', '');
  HB.ar(1, 1, ''); HB.ar(1, 2, ''); HB.ar(2, 1, '');
  HB.hotel('1 room left', '');
  HB.money('not paid', '');
};

HB.reset();
HB.strip('LONG WEEKEND', 'One room. Every site selling it.', '');
MSD.after(500, function(){ MSD.punch('#hb-hotel', 2); MSD.sfx.focus(); });
MSD.after(1300, function(){ MSD.punch('#hb-tr-1', 3); MSD.sfx.pop(); });
MSD.after(1800, function(){ MSD.punch('#hb-tr-2', 4); MSD.sfx.pop(); });
MSD.after(2800, function(){ HB.strip('BOTH SEE IT', 'Two travellers, one room, 1 left on both screens.', ''); });

